:root {
  color-scheme: light;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --panel-bg: #eaf2ff;
  --panel-border: #c5d6f3;
  --text: #172033;
  --muted: #536176;
  --button-bg: #f8fbff;
  --button-border: #b7c8e5;
  --button-active: #0d56c9;
  --button-active-text: #ffffff;
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #10141c;
  color: var(--text);
}

button,
input {
  font: inherit;
}

.app {
  display: grid;
  grid-template-columns: minmax(220px, 280px) minmax(0, 1fr);
  width: 100vw;
  height: 100vh;
  min-width: 320px;
  background: #dfeaff;
}

.panel {
  display: flex;
  flex-direction: column;
  gap: 22px;
  padding: 26px 20px;
  min-width: 0;
  border-right: 1px solid var(--panel-border);
  background: linear-gradient(180deg, var(--panel-bg) 0%, #f7fbff 100%);
}

.title-block {
  min-width: 0;
}

.eyebrow,
.title-block p,
.title-block h1 {
  margin: 0;
}

.eyebrow {
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: uppercase;
}

.title-block h1 {
  margin-top: 8px;
  color: #13223a;
  font-size: clamp(20px, 3vw, 28px);
  line-height: 1.05;
  overflow-wrap: anywhere;
}

.title-block p:last-child {
  margin-top: 4px;
  color: #1f304d;
  font-size: 18px;
}

.mode-switch {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--button-border);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.74);
}

.mode-button,
.run-row button {
  min-height: 38px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: #203451;
  cursor: pointer;
}

.mode-button.active {
  border-color: #0a47aa;
  background: var(--button-active);
  color: var(--button-active-text);
}

.legend {
  display: grid;
  grid-template-columns: 42px 1fr;
  gap: 12px;
  align-items: stretch;
  min-height: 300px;
}

.legend-ramp {
  height: 100%;
  min-height: 300px;
  border: 1px solid rgba(16, 23, 36, 0.36);
  background: linear-gradient(
    to top,
    #005bff 0%,
    #00b8ff 18%,
    #22d7d8 30%,
    #02c330 47%,
    #daf500 64%,
    #ffb500 82%,
    #ff6500 100%
  );
}

.legend-labels {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  color: #1c2b45;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: clamp(12px, 1.8vw, 18px);
  line-height: 1;
  white-space: nowrap;
}

.controls {
  display: grid;
  gap: 14px;
  margin-top: auto;
}

.controls label {
  display: grid;
  gap: 7px;
  color: #263852;
  font-size: 13px;
  font-weight: 700;
}

input[type="range"] {
  width: 100%;
  accent-color: #0d56c9;
}

.run-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.run-row button {
  border-color: var(--button-border);
  background: var(--button-bg);
  font-weight: 700;
}

.stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin: 0;
}

.stats div {
  min-width: 0;
  padding: 10px 12px;
  border: 1px solid rgba(141, 160, 194, 0.6);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.55);
}

.stats dt {
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0;
  text-transform: uppercase;
}

.stats dd {
  margin: 3px 0 0;
  color: #16233a;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 18px;
}

.viewport {
  position: relative;
  min-width: 0;
  min-height: 0;
  background: #e9eef8;
}

#stage {
  display: block;
  width: 100%;
  height: 100%;
}

.app[data-mode="beer"] {
  --panel-bg: #fbfbfa;
  --panel-border: #d6d1c8;
  --button-border: #cfc4b2;
  --button-active: #4c2d10;
  background: #fafafa;
}

.app[data-mode="beer"] .panel {
  background: linear-gradient(180deg, #ffffff 0%, #f6f2ea 100%);
}

.app[data-mode="beer"] .legend-ramp {
  background: linear-gradient(to top, #fff9eb 0%, #e6bd74 37%, #855524 68%, #080603 100%);
}

@media (max-width: 760px) {
  body {
    overflow: auto;
  }

  .app {
    grid-template-columns: 1fr;
    grid-template-rows: auto minmax(430px, 1fr);
    min-height: 100vh;
    height: auto;
  }

  .panel {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
    padding: 16px;
    border-right: 0;
    border-bottom: 1px solid var(--panel-border);
  }

  .title-block,
  .mode-switch,
  .legend,
  .controls,
  .run-row,
  .stats {
    min-width: 0;
  }

  .legend {
    grid-column: 1 / -1;
    min-height: 88px;
    grid-template-columns: 1fr;
    grid-template-rows: 24px auto;
  }

  .legend-ramp {
    width: 100%;
    min-height: 24px;
    height: 24px;
    background: linear-gradient(
      to right,
      #005bff 0%,
      #00b8ff 18%,
      #22d7d8 30%,
      #02c330 47%,
      #daf500 64%,
      #ffb500 82%,
      #ff6500 100%
    );
  }

  .app[data-mode="beer"] .legend-ramp {
    background: linear-gradient(to right, #fff9eb 0%, #e6bd74 37%, #855524 68%, #080603 100%);
  }

  .legend-labels {
    flex-direction: row-reverse;
    font-size: 12px;
  }

  .controls {
    margin-top: 0;
    grid-column: 1 / -1;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 520px) {
  .panel {
    grid-template-columns: 1fr;
  }

  .controls {
    grid-template-columns: 1fr;
  }
}

