(function () {
  "use strict";

  var SIM_W = 1000;
  var SIM_H = 650;
  var FIELD_W = 190;
  var FIELD_H = Math.round((FIELD_W * SIM_H) / SIM_W);
  var DPR_LIMIT = 1.75;

  var app = document.querySelector(".app");
  var canvas = document.getElementById("stage");
  var ctx = canvas.getContext("2d", { alpha: false });
  var fpsValue = document.getElementById("fpsValue");
  var particleValue = document.getElementById("particleValue");
  var runButton = document.getElementById("runButton");
  var resetButton = document.getElementById("resetButton");
  var flowControl = document.getElementById("flowControl");
  var turbulenceControl = document.getElementById("turbulenceControl");
  var resolutionControl = document.getElementById("resolutionControl");
  var legendLabels = document.getElementById("legendLabels");
  var fieldTitle = document.getElementById("fieldTitle");
  var fieldSubtitle = document.getElementById("fieldSubtitle");
  var modeButtons = Array.prototype.slice.call(document.querySelectorAll("[data-mode-button]"));

  var fieldCanvas = document.createElement("canvas");
  var fieldCtx = fieldCanvas.getContext("2d", { willReadFrequently: false });
  var field;
  var imageData;
  var particles = [];
  var running = true;
  var mode = "contour";
  var simTime = 0;
  var lastTime = performance.now();
  var frameAccumulator = 0;
  var frameCount = 0;
  var lastFpsUpdate = performance.now();
  var lastMeasuredFps = 0;
  var dpr = 1;
  var view = { x: 0, y: 0, w: 1, h: 1, scale: 1 };

  var glass = {
    cx: 710,
    cy: 304,
    length: 430,
    width: 138,
    angle: -0.64
  };

  glass.u = { x: Math.cos(glass.angle), y: Math.sin(glass.angle) };
  glass.v = { x: -Math.sin(glass.angle), y: Math.cos(glass.angle) };

  var lowerCup = [
    { x: 340, y: 390 },
    { x: 515, y: 390 },
    { x: 490, y: 640 },
    { x: 385, y: 640 }
  ];

  var streamStart = localToWorld(-glass.length * 0.49, glass.width * 0.34);
  var streamMidA = { x: 466, y: 445 };
  var streamMidB = { x: 374, y: 520 };
  var streamEnd = { x: 392, y: 397 };

  function initField() {
    FIELD_W = Number(resolutionControl.value);
    FIELD_H = Math.round((FIELD_W * SIM_H) / SIM_W);
    fieldCanvas.width = FIELD_W;
    fieldCanvas.height = FIELD_H;
    field = new Float32Array(FIELD_W * FIELD_H);
    imageData = fieldCtx.createImageData(FIELD_W, FIELD_H);
  }

  function localToWorld(s, n) {
    return {
      x: glass.cx + glass.u.x * s + glass.v.x * n,
      y: glass.cy + glass.u.y * s + glass.v.y * n
    };
  }

  function worldToLocal(x, y) {
    var dx = x - glass.cx;
    var dy = y - glass.cy;
    return {
      s: dx * glass.u.x + dy * glass.u.y,
      n: dx * glass.v.x + dy * glass.v.y
    };
  }

  function random(min, max) {
    return min + Math.random() * (max - min);
  }

  function clamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }

  function smoother(value) {
    var x = clamp(value, 0, 1);
    return x * x * (3 - 2 * x);
  }

  function pointInPolygon(point, polygon) {
    var inside = false;
    for (var i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
      var xi = polygon[i].x;
      var yi = polygon[i].y;
      var xj = polygon[j].x;
      var yj = polygon[j].y;
      var intersects = yi > point.y !== yj > point.y && point.x < ((xj - xi) * (point.y - yi)) / (yj - yi) + xi;
      if (intersects) {
        inside = !inside;
      }
    }
    return inside;
  }

  function randomPointInCup() {
    for (var i = 0; i < 40; i++) {
      var p = { x: random(354, 502), y: random(410, 632) };
      if (pointInPolygon(p, lowerCup)) {
        return p;
      }
    }
    return { x: random(390, 470), y: random(475, 628) };
  }

  function resetParticles() {
    particles = [];

    for (var i = 0; i < 250; i++) {
      var cupPoint = randomPointInCup();
      particles.push({
        type: "cup",
        x: cupPoint.x,
        y: cupPoint.y,
        vx: random(-10, 10),
        vy: random(-8, 8),
        phase: random(0, Math.PI * 2),
        radius: random(15, 30),
        strength: random(0.45, 1)
      });
    }

    for (var j = 0; j < 210; j++) {
      var s = random(-185, 170);
      var surface = glassSurfaceN(s, 0);
      var n = random(surface + 8, glass.width * 0.47);
      var world = localToWorld(s, n);
      particles.push({
        type: "glass",
        s: s,
        n: n,
        x: world.x,
        y: world.y,
        vs: random(-8, 8),
        vn: random(-5, 5),
        phase: random(0, Math.PI * 2),
        radius: random(18, 34),
        strength: random(0.6, 1)
      });
    }

    for (var k = 0; k < 110; k++) {
      particles.push(makeStreamParticle(k / 110));
    }

    particleValue.textContent = String(particles.length);
  }

  function makeStreamParticle(offset) {
    return {
      type: "stream",
      t: offset === undefined ? random(0, 0.12) : offset,
      lane: random(-1, 1),
      phase: random(0, Math.PI * 2),
      radius: random(8, 18),
      strength: random(0.68, 1),
      x: streamStart.x,
      y: streamStart.y
    };
  }

  function glassSurfaceN(s, time) {
    var normalized = (s + glass.length * 0.45) / (glass.length * 0.9);
    var wave = Math.sin(normalized * 5.5 + time * 1.25) * 7 + Math.sin(normalized * 11 - time * 0.7) * 2.5;
    return -24 + wave;
  }

  function streamPoint(t) {
    var one = 1 - t;
    var x =
      one * one * one * streamStart.x +
      3 * one * one * t * streamMidA.x +
      3 * one * t * t * streamMidB.x +
      t * t * t * streamEnd.x;
    var y =
      one * one * one * streamStart.y +
      3 * one * one * t * streamMidA.y +
      3 * one * t * t * streamMidB.y +
      t * t * t * streamEnd.y;
    return { x: x, y: y };
  }

  function streamNormal(t) {
    var one = 1 - t;
    var dx =
      3 * one * one * (streamMidA.x - streamStart.x) +
      6 * one * t * (streamMidB.x - streamMidA.x) +
      3 * t * t * (streamEnd.x - streamMidB.x);
    var dy =
      3 * one * one * (streamMidA.y - streamStart.y) +
      6 * one * t * (streamMidB.y - streamMidA.y) +
      3 * t * t * (streamEnd.y - streamMidB.y);
    var length = Math.max(0.001, Math.sqrt(dx * dx + dy * dy));
    return { x: -dy / length, y: dx / length };
  }

  function updateParticles(dt) {
    var flow = Number(flowControl.value);
    var turbulence = Number(turbulenceControl.value);

    for (var i = 0; i < particles.length; i++) {
      var p = particles[i];
      if (p.type === "stream") {
        updateStreamParticle(p, dt, flow, turbulence);
      } else if (p.type === "cup") {
        updateCupParticle(p, dt, turbulence);
      } else {
        updateGlassParticle(p, dt, turbulence, flow);
      }
    }
  }

  function updateStreamParticle(p, dt, flow, turbulence) {
    p.t += dt * (0.48 + flow * 0.36) * (0.72 + p.strength * 0.55);
    if (p.t > 1) {
      var fresh = makeStreamParticle(0);
      p.t = fresh.t;
      p.lane = fresh.lane;
      p.phase = fresh.phase;
      p.radius = fresh.radius;
      p.strength = fresh.strength;
    }

    var center = streamPoint(p.t);
    var normal = streamNormal(p.t);
    var neck = 1 - Math.abs(p.t - 0.38) * 0.52;
    var flutter = Math.sin(simTime * 14 + p.phase + p.t * 9) * 7 * turbulence;
    var offset = p.lane * (10 + 9 * neck) + flutter;
    p.x = center.x + normal.x * offset;
    p.y = center.y + normal.y * offset;
  }

  function updateCupParticle(p, dt, turbulence) {
    var c1x = 430 + Math.sin(simTime * 0.8) * 20;
    var c1y = 535 + Math.cos(simTime * 0.55) * 20;
    var c2x = 444 + Math.sin(simTime * 1.1 + 2.4) * 32;
    var c2y = 496 + Math.cos(simTime * 0.9) * 28;
    var dx1 = p.x - c1x;
    var dy1 = p.y - c1y;
    var dx2 = p.x - c2x;
    var dy2 = p.y - c2y;
    var swirl1 = 0.0028 * turbulence;
    var swirl2 = -0.0021 * turbulence;
    var jetPull = Math.max(0, 1 - Math.abs(p.x - streamEnd.x) / 95) * Math.max(0, 1 - Math.abs(p.y - 420) / 130);

    p.vx += (-dy1 * swirl1 - dy2 * swirl2 + Math.sin(simTime * 3 + p.phase) * 0.9 * turbulence + jetPull * 0.6) * dt * 60;
    p.vy += (dx1 * swirl1 + dx2 * swirl2 + Math.cos(simTime * 2.4 + p.phase) * 0.7 * turbulence + jetPull * 1.2) * dt * 60;
    p.vx *= Math.pow(0.977, dt * 60);
    p.vy *= Math.pow(0.977, dt * 60);
    p.x += p.vx * dt;
    p.y += p.vy * dt;

    if (!pointInPolygon(p, lowerCup) || p.y < 392 || p.y > 642) {
      var replacement = randomPointInCup();
      p.x = replacement.x;
      p.y = replacement.y;
      p.vx = random(-8, 8);
      p.vy = random(-6, 6);
    }
  }

  function updateGlassParticle(p, dt, turbulence, flow) {
    var surface = glassSurfaceN(p.s, simTime);
    var drainBias = p.s < -150 ? -18 * flow : -7 * flow;
    p.vs += (Math.sin(simTime * 1.7 + p.phase) * 7 * turbulence + drainBias) * dt;
    p.vn += (Math.cos(simTime * 2.3 + p.phase) * 5 * turbulence + (glass.width * 0.23 - p.n) * 0.11) * dt;
    p.vs *= Math.pow(0.985, dt * 60);
    p.vn *= Math.pow(0.983, dt * 60);
    p.s += p.vs * dt;
    p.n += p.vn * dt;

    if (p.s < -205 || p.n < surface + 4 || p.n > glass.width * 0.5 || p.s > 188) {
      p.s = random(-175, 178);
      p.n = random(glassSurfaceN(p.s, simTime) + 8, glass.width * 0.47);
      p.vs = random(-5, 6);
      p.vn = random(-3, 4);
    }

    var world = localToWorld(p.s, p.n);
    p.x = world.x;
    p.y = world.y;
  }

  function buildField() {
    field.fill(0);

    for (var i = 0; i < particles.length; i++) {
      var p = particles[i];
      var radius = p.radius;
      var strength = p.strength;

      if (p.type === "stream") {
        radius *= 0.78;
        strength *= 1.08;
      } else if (p.type === "cup") {
        var depth = smoother((p.y - 395) / 230);
        strength *= 0.35 + depth * 0.68;
      }

      splat(p.x, p.y, radius, strength);
    }
  }

  function splat(x, y, radius, strength) {
    var gx = (x / SIM_W) * FIELD_W;
    var gy = (y / SIM_H) * FIELD_H;
    var gr = Math.max(1.3, (radius / SIM_W) * FIELD_W);
    var minX = Math.max(0, Math.floor(gx - gr * 2));
    var maxX = Math.min(FIELD_W - 1, Math.ceil(gx + gr * 2));
    var minY = Math.max(0, Math.floor(gy - gr * 2));
    var maxY = Math.min(FIELD_H - 1, Math.ceil(gy + gr * 2));
    var inv = 1 / (2 * gr * gr);

    for (var yy = minY; yy <= maxY; yy++) {
      var dy = yy - gy;
      for (var xx = minX; xx <= maxX; xx++) {
        var dx = xx - gx;
        var falloff = Math.exp(-(dx * dx + dy * dy) * inv);
        if (falloff < 0.02) {
          continue;
        }
        var index = yy * FIELD_W + xx;
        field[index] = Math.min(1, field[index] + falloff * strength * 0.23);
      }
    }
  }

  function colorContour(v) {
    var q = Math.floor(clamp(v, 0, 1) * 9) / 8;
    if (q < 0.08) return [0, 91, 255, 255];
    if (q < 0.18) return [0, 138, 255, 255];
    if (q < 0.3) return [0, 190, 238, 255];
    if (q < 0.43) return [26, 210, 176, 255];
    if (q < 0.56) return [0, 196, 44, 255];
    if (q < 0.68) return [136, 230, 0, 255];
    if (q < 0.8) return [245, 238, 0, 255];
    if (q < 0.9) return [255, 183, 0, 255];
    return [255, 101, 0, 255];
  }

  function colorBeer(v) {
    var x = clamp(v, 0, 1);
    if (x < 0.02) return [255, 249, 235, 0];
    var r;
    var g;
    var b;
    if (x < 0.42) {
      var a = x / 0.42;
      r = 255 - a * 47;
      g = 248 - a * 73;
      b = 226 - a * 116;
    } else if (x < 0.72) {
      var m = (x - 0.42) / 0.3;
      r = 208 - m * 82;
      g = 175 - m * 94;
      b = 110 - m * 70;
    } else {
      var d = (x - 0.72) / 0.28;
      r = 126 - d * 114;
      g = 81 - d * 75;
      b = 40 - d * 35;
    }
    return [r, g, b, 85 + Math.pow(x, 0.75) * 155];
  }

  function renderFieldImage() {
    var data = imageData.data;
    var colorFn = mode === "beer" ? colorBeer : colorContour;
    for (var i = 0; i < field.length; i++) {
      var v = clamp(field[i], 0, 1);
      if (mode === "beer") {
        var ripple = (Math.sin((i % FIELD_W) * 0.33 + simTime * 2.1) + Math.cos(Math.floor(i / FIELD_W) * 0.27 - simTime * 1.5)) * 0.045;
        v = clamp(v + ripple * v, 0, 1);
      }
      var color = colorFn(v);
      var j = i * 4;
      data[j] = color[0];
      data[j + 1] = color[1];
      data[j + 2] = color[2];
      data[j + 3] = color[3];
    }
    fieldCtx.putImageData(imageData, 0, 0);
  }

  function render() {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = mode === "beer" ? "#f8f8f7" : "#e3edff";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    updateView();
    ctx.save();
    ctx.translate(view.x, view.y);
    ctx.scale(view.scale, view.scale);
    if (mode === "beer") {
      drawBeerScene();
    } else {
      drawContourScene();
    }
    ctx.restore();
  }

  function drawContourScene() {
    ctx.fillStyle = "#005dff";
    ctx.fillRect(0, 0, SIM_W, SIM_H);
    ctx.imageSmoothingEnabled = true;
    ctx.drawImage(fieldCanvas, 0, 0, SIM_W, SIM_H);
    drawStreamCore("contour");
    drawLowerCup("#dbeeff", "rgba(8, 38, 92, 0.5)");
    drawTiltedGlass("#dbeeff", "rgba(7, 31, 82, 0.38)");
    drawGlassSurface("#62f0ef", 2.5);
    drawAxes();
    drawAnsysMark();
  }

  function drawBeerScene() {
    ctx.fillStyle = "#f9f9f8";
    ctx.fillRect(0, 0, SIM_W, SIM_H);
    drawSoftShadow();
    drawTiltedGlass("rgba(215, 219, 219, 0.55)", "rgba(255, 255, 255, 0.26)", true);
    drawLowerCup("rgba(215, 219, 219, 0.52)", "rgba(255, 255, 255, 0.04)", true);
    ctx.imageSmoothingEnabled = true;
    ctx.drawImage(fieldCanvas, 0, 0, SIM_W, SIM_H);
    drawStreamCore("beer");
    drawGlassSurface("rgba(89, 57, 24, 0.68)", 3);
    drawGlassHighlights();
  }

  function drawStreamCore(sceneMode) {
    ctx.save();
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    for (var i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.moveTo(streamStart.x, streamStart.y);
      ctx.bezierCurveTo(streamMidA.x, streamMidA.y, streamMidB.x, streamMidB.y, streamEnd.x, streamEnd.y);
      if (sceneMode === "beer") {
        ctx.strokeStyle = i === 0 ? "rgba(82, 48, 17, 0.34)" : i === 1 ? "rgba(187, 132, 58, 0.26)" : "rgba(253, 232, 169, 0.22)";
      } else {
        ctx.strokeStyle = i === 0 ? "rgba(255, 105, 0, 0.92)" : i === 1 ? "rgba(16, 208, 146, 0.68)" : "rgba(0, 169, 255, 0.38)";
      }
      ctx.lineWidth = sceneMode === "beer" ? 20 - i * 6 : 28 - i * 8;
      ctx.stroke();
    }
    ctx.restore();
  }

  function drawLowerCup(strokeStyle, fillStyle, glassy) {
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(lowerCup[0].x, lowerCup[0].y);
    for (var i = 1; i < lowerCup.length; i++) {
      ctx.lineTo(lowerCup[i].x, lowerCup[i].y);
    }
    ctx.closePath();
    ctx.fillStyle = fillStyle || "transparent";
    ctx.fill();
    ctx.lineWidth = glassy ? 6 : 3;
    ctx.strokeStyle = strokeStyle;
    ctx.stroke();
    if (glassy) {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.8)";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(355, 400);
      ctx.lineTo(397, 631);
      ctx.stroke();
    }
    ctx.restore();
  }

  function glassCorners() {
    var halfL = glass.length / 2;
    var halfW = glass.width / 2;
    return [
      localToWorld(-halfL, -halfW),
      localToWorld(halfL, -halfW),
      localToWorld(halfL, halfW),
      localToWorld(-halfL, halfW)
    ];
  }

  function drawTiltedGlass(strokeStyle, fillStyle, glassy) {
    var corners = glassCorners();
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(corners[0].x, corners[0].y);
    ctx.lineTo(corners[1].x, corners[1].y);
    ctx.lineTo(corners[2].x, corners[2].y);
    ctx.lineTo(corners[3].x, corners[3].y);
    ctx.closePath();
    ctx.fillStyle = fillStyle || "transparent";
    ctx.fill();
    ctx.lineWidth = glassy ? 8 : 3;
    ctx.strokeStyle = strokeStyle;
    ctx.stroke();

    if (glassy) {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.72)";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(corners[0].x + 14, corners[0].y + 8);
      ctx.lineTo(corners[1].x - 22, corners[1].y + 10);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(corners[3].x + 20, corners[3].y - 8);
      ctx.lineTo(corners[2].x - 10, corners[2].y - 20);
      ctx.stroke();
    }
    ctx.restore();
  }

  function drawGlassSurface(strokeStyle, width) {
    ctx.save();
    ctx.beginPath();
    for (var i = 0; i <= 32; i++) {
      var s = -185 + (i / 32) * 360;
      var p = localToWorld(s, glassSurfaceN(s, simTime));
      if (i === 0) {
        ctx.moveTo(p.x, p.y);
      } else {
        ctx.lineTo(p.x, p.y);
      }
    }
    ctx.lineWidth = width;
    ctx.strokeStyle = strokeStyle;
    ctx.stroke();
    ctx.restore();
  }

  function drawGlassHighlights() {
    ctx.save();
    ctx.globalCompositeOperation = "screen";
    ctx.strokeStyle = "rgba(255, 255, 255, 0.5)";
    ctx.lineWidth = 7;
    ctx.beginPath();
    ctx.moveTo(563, 245);
    ctx.bezierCurveTo(640, 148, 780, 103, 832, 198);
    ctx.stroke();
    ctx.globalCompositeOperation = "source-over";
    ctx.restore();
  }

  function drawSoftShadow() {
    ctx.save();
    ctx.fillStyle = "rgba(0, 0, 0, 0.08)";
    ctx.beginPath();
    ctx.ellipse(618, 612, 260, 34, -0.14, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  function drawAxes() {
    ctx.save();
    ctx.translate(906, 572);
    ctx.lineWidth = 4;
    ctx.strokeStyle = "#f33423";
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(54, 0);
    ctx.stroke();
    ctx.fillStyle = "#f33423";
    ctx.beginPath();
    ctx.moveTo(62, 0);
    ctx.lineTo(45, -9);
    ctx.lineTo(45, 9);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "#20b949";
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(0, -58);
    ctx.stroke();
    ctx.fillStyle = "#20b949";
    ctx.beginPath();
    ctx.moveTo(0, -66);
    ctx.lineTo(-9, -48);
    ctx.lineTo(9, -48);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = "#0d47d7";
    ctx.beginPath();
    ctx.arc(0, 0, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#ef4435";
    ctx.font = "18px sans-serif";
    ctx.fillText("X", 72, 8);
    ctx.fillStyle = "#2dad53";
    ctx.fillText("Y", 8, -68);
    ctx.restore();
  }

  function drawAnsysMark() {
    ctx.save();
    ctx.globalAlpha = 0.85;
    ctx.fillStyle = "#eaf2ff";
    ctx.font = "700 23px sans-serif";
    ctx.fillText("ANSYS", 884, 38);
    ctx.font = "14px sans-serif";
    ctx.fillText("2019 R3", 901, 58);
    ctx.font = "11px sans-serif";
    ctx.fillText("ACADEMIC", 889, 78);
    ctx.restore();
  }

  function updateView() {
    var cssW = canvas.clientWidth;
    var cssH = canvas.clientHeight;
    var scale = Math.min(cssW / SIM_W, cssH / SIM_H);
    view.w = SIM_W * scale;
    view.h = SIM_H * scale;
    view.x = (cssW - view.w) * 0.5;
    view.y = (cssH - view.h) * 0.5;
    view.scale = scale;
  }

  function resize() {
    dpr = Math.min(window.devicePixelRatio || 1, DPR_LIMIT);
    var rect = canvas.getBoundingClientRect();
    canvas.width = Math.max(1, Math.floor(rect.width * dpr));
    canvas.height = Math.max(1, Math.floor(rect.height * dpr));
  }

  function setMode(nextMode) {
    mode = nextMode;
    app.dataset.mode = mode;
    modeButtons.forEach(function (button) {
      button.classList.toggle("active", button.dataset.modeButton === mode);
    });
    if (mode === "beer") {
      fieldTitle.textContent = "Volume Fraction of beer";
      fieldSubtitle.textContent = "";
      legendLabels.innerHTML = "<span>1.0</span><span>0.50</span><span>0.0</span>";
    } else {
      fieldTitle.textContent = "Water.Volume Fraction";
      fieldSubtitle.textContent = "Contour 1";
      legendLabels.innerHTML =
        "<span>1.000e+00</span><span>8.889e-01</span><span>7.778e-01</span><span>6.667e-01</span><span>5.556e-01</span><span>4.444e-01</span><span>3.333e-01</span><span>2.222e-01</span><span>1.111e-01</span><span>0.000e+00</span>";
    }
  }

  function tick(now) {
    var rawDt = Math.min(0.05, (now - lastTime) / 1000);
    lastTime = now;

    if (running) {
      var dt = Math.min(1 / 30, rawDt);
      simTime += dt;
      updateParticles(dt);
      buildField();
      renderFieldImage();
    }

    render();
    frameCount++;
    frameAccumulator += rawDt;
