(function () {
  "use strict";

  var SIM_W = 1000;
  var SIM_H = 650;
  var FIELD_W = 200;
  var FIELD_H = Math.round((FIELD_W * SIM_H) / SIM_W);
  var DPR_LIMIT = 1.75;

  var app = document.querySelector(".app");
  var canvas = document.getElementById("stage");
  var ctx = canvas.getContext("2d", { alpha: false });
  var fpsValue = document.getElementById("fpsValue");
  var particleValue = document.getElementById("particleValue");
  var fillValue = document.getElementById("fillValue");
  var foamValue = document.getElementById("foamValue");
  var runButton = document.getElementById("runButton");
  var resetButton = document.getElementById("resetButton");
  var valveControl = document.getElementById("valveControl");
  var pressureControl = document.getElementById("pressureControl");
  var aerationControl = document.getElementById("aerationControl");
  var resolutionControl = document.getElementById("resolutionControl");
  var legendLabels = document.getElementById("legendLabels");
  var fieldTitle = document.getElementById("fieldTitle");
  var fieldSubtitle = document.getElementById("fieldSubtitle");
  var layerButtons = Array.prototype.slice.call(document.querySelectorAll("[data-layer-button]"));

  var fieldCanvas = document.createElement("canvas");
  var fieldCtx = fieldCanvas.getContext("2d", { willReadFrequently: false });
  var waterField;
  var airField;
  var imageData;

  var droplets = [];
  var tracers = [];
  var bubbles = [];
  var foam = [];
  var spawnBudget = 0;
  var running = true;
  var layer = "vof";
  var simTime = 0;
  var lastTime = performance.now();
  var lastFpsUpdate = performance.now();
  var frameAccumulator = 0;
  var frameCount = 0;
  var dpr = 1;
  var view = { x: 0, y: 0, scale: 1 };

  var fillLevel = 0.18;
  var waveAmp = 4;
  var slosh = 0;
  var impactEnergy = 0;

  var cup = {
    cx: 600,
    topY: 150,
    bottomY: 610,
    topWidth: 365,
    bottomWidth: 245
  };

  var faucet = {
    x: 600,
    topY: 30,
    nozzleY: 132,
    width: 32
  };

  function initField() {
    FIELD_W = Number(resolutionControl.value);
    FIELD_H = Math.round((FIELD_W * SIM_H) / SIM_W);
    fieldCanvas.width = FIELD_W;
    fieldCanvas.height = FIELD_H;
    waterField = new Float32Array(FIELD_W * FIELD_H);
    airField = new Float32Array(FIELD_W * FIELD_H);
    imageData = fieldCtx.createImageData(FIELD_W, FIELD_H);
  }

  function resetSimulation() {
    droplets = [];
    bubbles = [];
    foam = [];
    tracers = [];
    spawnBudget = 0;
    simTime = 0;
    fillLevel = 0.18;
    waveAmp = 4;
    slosh = 0;
    impactEnergy = 0;

    for (var i = 0; i < 360; i++) {
      tracers.push(makeTracer());
    }
  }

  function random(min, max) {
    return min + Math.random() * (max - min);
  }

  function clamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }

  function smoothstep(edge0, edge1, value) {
    var x = clamp((value - edge0) / (edge1 - edge0), 0, 1);
    return x * x * (3 - 2 * x);
  }

  function halfWidthAt(y) {
    var t = clamp((y - cup.topY) / (cup.bottomY - cup.topY), 0, 1);
    return cup.topWidth * 0.5 + (cup.bottomWidth * 0.5 - cup.topWidth * 0.5) * t;
  }

  function leftWallAt(y) {
    return cup.cx - halfWidthAt(y);
  }

  function rightWallAt(y) {
    return cup.cx + halfWidthAt(y);
  }

  function insideCup(x, y) {
    return y >= cup.topY && y <= cup.bottomY && x >= leftWallAt(y) && x <= rightWallAt(y);
  }

  function usableHeight() {
    return cup.bottomY - cup.topY - 34;
  }

  function baseSurfaceY() {
    return cup.bottomY - fillLevel * usableHeight();
  }

  function surfaceY(x) {
    var base = baseSurfaceY();
    var h = halfWidthAt(base) * 0.96;
    var nx = clamp((x - cup.cx) / h, -1.15, 1.15);
    var edgeFade = clamp(1 - Math.abs(nx) * 0.74, 0, 1);
    var wave =
      Math.sin(nx * Math.PI * 2.2 + simTime * 3.1 + slosh) * waveAmp * edgeFade +
      Math.sin(nx * Math.PI * 5.1 - simTime * 2.4) * waveAmp * 0.26 * edgeFade;
    var dent = Math.exp(-Math.pow((x - faucet.x) / 46, 2)) * impactEnergy * 16;
    return base + wave + dent;
  }

  function belowSurface(x, y) {
    return insideCup(x, y) && y >= surfaceY(x);
  }

  function makeTracer() {
    var p = randomWaterPoint();
    return {
      x: p.x,
      y: p.y,
      phase: random(0, Math.PI * 2),
      strength: random(0.35, 1)
    };
  }

  function randomWaterPoint() {
    for (var i = 0; i < 80; i++) {
      var y = random(baseSurfaceY() + 12, cup.bottomY - 12);
      var x = random(leftWallAt(y) + 12, rightWallAt(y) - 12);
      if (belowSurface(x, y)) {
        return { x: x, y: y };
      }
    }
    return { x: cup.cx + random(-40, 40), y: cup.bottomY - random(30, 120) };
  }

  function controls() {
    return {
      valve: Number(valveControl.value),
      pressure: Number(pressureControl.value),
      aeration: Number(aerationControl.value)
    };
  }

  function update(dt) {
    var c = controls();
    var inlet = c.valve * c.pressure;
    fillLevel = clamp(fillLevel + inlet * dt * 0.026, 0.06, 0.9);
    impactEnergy += (inlet - impactEnergy) * clamp(dt * 7, 0, 1);
    waveAmp = clamp(waveAmp * Math.pow(0.987, dt * 60) + impactEnergy * dt * 7.5, 1.5, 22);
    slosh += dt * (0.6 + impactEnergy * 0.65);

    spawnInlet(dt, c);
    updateDroplets(dt, c);
    updateTracers(dt, c);
    updateBubbles(dt, c);
    updateFoam(dt, c);
    buildFields();
    renderFieldImage();
    updateStats();
  }

  function spawnInlet(dt, c) {
    if (c.valve <= 0.01) {
      return;
    }

    var rate = (c.valve * 90 + Math.pow(c.valve, 1.45) * 520) * c.pressure;
    spawnBudget += rate * dt;
    var maxDroplets = 1150;

    while (spawnBudget >= 1 && droplets.length < maxDroplets) {
      spawnBudget -= 1;
      var jetSpread = 1.8 + c.valve * 8 + c.pressure * 2.8;
      droplets.push({
        type: "jet",
        x: faucet.x + random(-jetSpread, jetSpread),
        y: faucet.nozzleY,
        vx: random(-10, 10) * c.aeration + Math.sin(simTime * 11) * c.valve * 8,
        vy: 230 + c.pressure * 205 + c.valve * 115,
        r: random(2.2, 4.6) + c.valve * 1.5,
        life: 2.2,
        phase: random(0, Math.PI * 2)
      });
    }
  }

  function updateDroplets(dt, c) {
    var next = [];
    for (var i = 0; i < droplets.length; i++) {
      var p = droplets[i];
      p.life -= dt;
      p.vy += 760 * dt;
      p.vx += Math.sin(simTime * 5 + p.phase + p.y * 0.018) * c.aeration * 22 * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;

      var hitWater = insideCup(p.x, p.y) && p.y >= surfaceY(p.x) - 4;
      if (hitWater) {
        absorbDroplet(p, c);
        continue;
      }

      if (p.life <= 0 || p.y > SIM_H + 40 || p.x < -60 || p.x > SIM_W + 60) {
        continue;
      }

      next.push(p);
    }
    droplets = next;
  }

  function absorbDroplet(p, c) {
    var speed = Math.sqrt(p.vx * p.vx + p.vy * p.vy);
    var energy = clamp((speed - 250) / 580, 0, 1) * clamp(c.valve * c.pressure, 0, 2.2);
    waveAmp = clamp(waveAmp + energy * 0.8, 1.5, 25);
    slosh += p.vx * 0.0015;

    var splashCount = Math.floor(energy * c.aeration * 4.5);
    for (var i = 0; i < splashCount && droplets.length < 1150; i++) {
      droplets.push({
        type: "splash",
        x: p.x + random(-10, 10),
        y: surfaceY(p.x) - random(0, 8),
        vx: random(-115, 115) * (0.45 + c.aeration * 0.35),
        vy: random(-230, -70) * (0.55 + c.pressure * 0.12),
        r: random(1.8, 3.8),
        life: random(0.45, 0.9),
        phase: random(0, Math.PI * 2)
      });
    }

    var bubbleCount = Math.floor(energy * c.aeration * 9);
    for (var j = 0; j < bubbleCount && bubbles.length < 520; j++) {
      bubbles.push({
        x: p.x + random(-28, 28),
        y: surfaceY(p.x) + random(12, 82),
        vx: random(-18, 18) + p.vx * 0.015,
        vy: random(-18, -4),
        r: random(3, 11) * (0.8 + c.aeration * 0.15),
        life: random(2.2, 5.8),
        phase: random(0, Math.PI * 2),
        strength: random(0.4, 1)
      });
    }

    var foamCount = Math.floor(energy * c.aeration * 3.5);
    for (var k = 0; k < foamCount && foam.length < 380; k++) {
      spawnFoam(p.x + random(-36, 36), random(0.7, 1.2));
    }
  }

  function spawnFoam(x, strength) {
    var sy = surfaceY(x);
    if (!insideCup(x, sy + 3)) {
      return;
    }
    foam.push({
      x: x,
      y: sy - random(1, 7),
      vx: random(-26, 26),
      r: random(5, 15),
      life: random(3.0, 8.0),
      phase: random(0, Math.PI * 2),
      strength: strength
    });
  }

  function updateTracers(dt, c) {
    for (var i = 0; i < tracers.length; i++) {
      var p = tracers[i];
      var v = velocityAt(p.x, p.y, c);
      p.x += (v.x + Math.sin(simTime * 2.2 + p.phase) * 7 * c.aeration) * dt;
      p.y += (v.y + Math.cos(simTime * 2.7 + p.phase) * 5 * c.aeration) * dt;

      if (!belowSurface(p.x, p.y) || p.y > cup.bottomY - 8) {
        var r = randomWaterPoint();
        p.x = r.x;
        p.y = r.y;
      }
    }
  }

  function velocityAt(x, y, c) {
    var sy = surfaceY(x);
