        continue;
      }

      next.push(b);
    }
    bubbles = next;
  }

  function updateFoam(dt, c) {
    var next = [];
    for (var i = 0; i < foam.length; i++) {
      var f = foam[i];
      f.life -= dt * (0.32 + Math.max(0, 0.6 - c.valve) * 0.25);
      f.vx += Math.sin(simTime * 2 + f.phase) * 4 * dt;
      f.x += f.vx * dt;
