  function buildFields() {
    airField.fill(0);

    for (var yy = 0; yy < FIELD_H; yy++) {
      var y = (yy / (FIELD_H - 1)) * SIM_H;
      for (var xx = 0; xx < FIELD_W; xx++) {
        var x = (xx / (FIELD_W - 1)) * SIM_W;
        var index = yy * FIELD_W + xx;
        if (!insideCup(x, y)) {
          waterField[index] = 0;
          continue;
        }

        var sy = surfaceY(x);
        var base = smoothstep(sy - 13, sy + 15, y);
        waterField[index] = base;
      }
    }

    for (var i = 0; i < droplets.length; i++) {
