    }

    for (var k = 0; k < foam.length; k++) {
      var f = foam[k];
      splat(airField, f.x, f.y, f.r * 1.7, 0.35 + f.strength * 0.35);
    }

    for (var n = 0; n < waterField.length; n++) {
      waterField[n] = clamp(waterField[n] - clamp(airField[n], 0, 1) * 0.84, 0, 1);
