    var a = clamp(air, 0, 1);
    if (w < 0.02 && a < 0.02) return [255, 255, 255, 0];
    if (a > 0.05) {
      return [230 + a * 25, 248 + a * 7, 255, clamp(90 + a * 165, 0, 255)];
