    ctx.restore();
  }

  function drawFieldScene() {
    ctx.imageSmoothingEnabled = true;
    ctx.drawImage(fieldCanvas, 0, 0, SIM_W, SIM_H);
    drawFaucet(false);
    drawCup(false);
    drawSurface(layer === "air" ? "rgba(255,255,255,0.82)" : "rgba(210,255,255,0.88)", 2.5);
