  function drawSurface(strokeStyle, lineWidth) {
    ctx.save();
    ctx.beginPath();
    for (var i = 0; i <= 80; i++) {
      var yBase = baseSurfaceY();
      var x = leftWallAt(yBase) + (rightWallAt(yBase) - leftWallAt(yBase)) * (i / 80);
      var y = surfaceY(x);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
