  var resetButton = document.getElementById("resetButton");
  var valveControl = document.getElementById("valveControl");
  var pressureControl = document.getElementById("pressureControl");
  var aerationControl = document.getElementById("aerationControl");
  var cupAngleControl = document.getElementById("cupAngleControl");
  var faucetAngleControl = document.getElementById("faucetAngleControl");
  var resolutionControl = document.getElementById("resolutionControl");
  var legendLabels = document.getElementById("legendLabels");
  var fieldTitle = document.getElementById("fieldTitle");
  var fieldSubtitle = document.getElementById("fieldSubtitle");
  var layerButtons = Array.prototype.slice.call(document.querySelectorAll("[data-layer-button]"));

  var fieldCanvas = document.createElement("canvas");
  var fieldCtx = fieldCanvas.getContext("2d", { willReadFrequently: false });
  var waterField;
  var airField;
  var imageData;

  var particles = [];
  var bubbles = [];
  var foam = [];
  var spawnBudget = 0;
  var running = true;
  var layer = "vof";
  var simTime = 0;
  var lastTime = performance.now();
  var simAccumulator = 0;
  var lastFpsUpdate = performance.now();
  var frameAccumulator = 0;
  var frameCount = 0;
  var dpr = 1;
  var view = { x: 0, y: 0, scale: 1 };
  var containedCount = 0;
  var spilledCount = 0;

  var cup = {
    cx: 585,
    cy: 372,
    height: 510,
    topWidth: 470,
    bottomWidth: 310
  };

  var faucet = {
    x: 585,
    y: 76,
    length: 92
  };

  var cupFrame = makeCupFrame();
  var currentControls = controls();

  function initField() {
    FIELD_W = Number(resolutionControl.value);
    FIELD_H = Math.round((FIELD_W * SIM_H) / SIM_W);
    fieldCanvas.width = FIELD_W;
    fieldCanvas.height = FIELD_H;
    waterField = new Float32Array(FIELD_W * FIELD_H);
    airField = new Float32Array(FIELD_W * FIELD_H);
    imageData = fieldCtx.createImageData(FIELD_W, FIELD_H);
  }

  function resetSimulation() {
    particles = [];
    bubbles = [];
    foam = [];
    spawnBudget = 0;
    simTime = 0;
    simAccumulator = 0;
    containedCount = 0;
    spilledCount = 0;
  }

  function controls() {
    return {
      valve: Number(valveControl.value),
      pressure: Number(pressureControl.value),
      aeration: Number(aerationControl.value),
      cupAngle: (Number(cupAngleControl.value) * Math.PI) / 180,
      faucetAngle: (Number(faucetAngleControl.value) * Math.PI) / 180
    };
  }

  function random(min, max) {
    return min + Math.random() * (max - min);
  }

  function clamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }

  function smoothstep(edge0, edge1, value) {
    var x = clamp((value - edge0) / (edge1 - edge0), 0, 1);
    return x * x * (3 - 2 * x);
  }

  function makeCupFrame() {
    var angle = currentControls ? currentControls.cupAngle : 0;
    return {
      c: Math.cos(angle),
      s: Math.sin(angle),
      topY: -cup.height * 0.5,
      bottomY: cup.height * 0.5,
      topHalf: cup.topWidth * 0.5,
      bottomHalf: cup.bottomWidth * 0.5
    };
  }

  function worldToCup(x, y) {
    var dx = x - cup.cx;
    var dy = y - cup.cy;
    return {
      x: cupFrame.c * dx + cupFrame.s * dy,
      y: -cupFrame.s * dx + cupFrame.c * dy
    };
  }

  function cupToWorld(x, y) {
    return {
      x: cup.cx + cupFrame.c * x - cupFrame.s * y,
      y: cup.cy + cupFrame.s * x + cupFrame.c * y
    };
  }

  function velocityToCup(vx, vy) {
    return {
      x: cupFrame.c * vx + cupFrame.s * vy,
      y: -cupFrame.s * vx + cupFrame.c * vy
    };
  }

  function velocityToWorld(vx, vy) {
    return {
      x: cupFrame.c * vx - cupFrame.s * vy,
      y: cupFrame.s * vx + cupFrame.c * vy
    };
  }

  function halfWidthAtLocalY(y) {
    var t = clamp((y - cupFrame.topY) / cup.height, 0, 1);
    return cupFrame.topHalf + (cupFrame.bottomHalf - cupFrame.topHalf) * t;
  }

  function cupVertices() {
    return [
      cupToWorld(-cupFrame.topHalf, cupFrame.topY),
      cupToWorld(cupFrame.topHalf, cupFrame.topY),
      cupToWorld(cupFrame.bottomHalf, cupFrame.bottomY),
      cupToWorld(-cupFrame.bottomHalf, cupFrame.bottomY)
    ];
  }

  function nozzlePosition() {
    var a = currentControls.faucetAngle;
    return {
      x: faucet.x + Math.sin(a) * faucet.length,
      y: faucet.y + Math.cos(a) * faucet.length
    };
  }

  function faucetDirection() {
    var a = currentControls.faucetAngle;
    return {
      x: Math.sin(a),
      y: Math.cos(a)
    };
  }

  function update(dt) {
    currentControls = controls();
    cupFrame = makeCupFrame();
    simTime += dt;

    spawnWater(dt);
    integrateParticles(dt);
    solveParticleCollisions();
    solveCupCollisions();
    updateBubbles(dt);
    updateFoam(dt);
    pruneEscaped();
    buildFields();
    renderFieldImage();
    updateStats();
  }

  function spawnWater(dt) {
    var c = currentControls;
    if (c.valve <= 0.01 || particles.length >= MAX_PARTICLES) {
      return;
    }

    var rate = (110 + c.valve * 690) * c.valve * c.pressure;
    spawnBudget += rate * dt;
    var dir = faucetDirection();
    var noz = nozzlePosition();
    var normal = { x: -dir.y, y: dir.x };

    while (spawnBudget >= 1 && particles.length < MAX_PARTICLES) {
      spawnBudget -= 1;
      var spread = random(-8, 8) * (0.45 + c.valve * 0.75);
      var speed = 310 + c.pressure * 255 + c.valve * 120;
      particles.push({
        x: noz.x + normal.x * spread,
        y: noz.y + normal.y * spread,
        vx: dir.x * speed + random(-18, 18) * c.aeration,
        vy: dir.y * speed + random(-12, 12) * c.aeration,
        r: PARTICLE_R * random(0.86, 1.12),
        contained: false,
        age: 0,
        escaped: false
      });
    }
  }

  function integrateParticles(dt) {
    for (var i = 0; i < particles.length; i++) {
      var p = particles[i];
      p.age += dt;
      p.vy += GRAVITY * dt;
      p.vx *= Math.pow(0.999, dt * 60);
      p.vy *= Math.pow(0.999, dt * 60);
      p.x += p.vx * dt;
      p.y += p.vy * dt;

      var local = worldToCup(p.x, p.y);
      if (!p.contained && local.y > cupFrame.topY && local.y < cupFrame.bottomY && Math.abs(local.x) < halfWidthAtLocalY(local.y) - p.r) {
        p.contained = true;
        entrainAir(p);
      }

      if (p.contained && local.y < cupFrame.topY - p.r * 1.4) {
        p.contained = false;
        p.escaped = true;
        spilledCount++;
      }
    }
  }

  function solveParticleCollisions() {
    var grid = new Map();

    for (var i = 0; i < particles.length; i++) {
      var p = particles[i];
      var gx = Math.floor(p.x / CELL_SIZE);
      var gy = Math.floor(p.y / CELL_SIZE);
      var key = gx + "," + gy;
      var bucket = grid.get(key);
      if (!bucket) {
        bucket = [];
        grid.set(key, bucket);
      }
      bucket.push(i);
    }

    for (var pass = 0; pass < 2; pass++) {
      for (var pi = 0; pi < particles.length; pi++) {
        var a = particles[pi];
        var agx = Math.floor(a.x / CELL_SIZE);
        var agy = Math.floor(a.y / CELL_SIZE);
        for (var oy = -1; oy <= 1; oy++) {
          for (var ox = -1; ox <= 1; ox++) {
            var list = grid.get(agx + ox + "," + (agy + oy));
            if (!list) {
              continue;
            }
            for (var k = 0; k < list.length; k++) {
              var bi = list[k];
              if (bi <= pi) {
                continue;
              }
              separateParticles(a, particles[bi]);
            }
          }
        }
      }
    }
  }

  function separateParticles(a, b) {
    var dx = b.x - a.x;
    var dy = b.y - a.y;
    var minDist = a.r + b.r;
    var dist2 = dx * dx + dy * dy;
    if (dist2 <= 0.0001 || dist2 >= minDist * minDist) {
      return;
    }

    var dist = Math.sqrt(dist2);
    var nx = dx / dist;
    var ny = dy / dist;
    var overlap = (minDist - dist) * 0.5;
    a.x -= nx * overlap;
    a.y -= ny * overlap;
    b.x += nx * overlap;
    b.y += ny * overlap;

    var rel = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny;
    if (rel < 0) {
      var impulse = rel * 0.08;
      a.vx += nx * impulse;
      a.vy += ny * impulse;
      b.vx -= nx * impulse;
      b.vy -= ny * impulse;
    }
  }

  function solveCupCollisions() {
    for (var i = 0; i < particles.length; i++) {
      var p = particles[i];
      if (!p.contained) {
        continue;
      }
      collideWithCup(p);
    }
  }

  function collideWithCup(p) {
    var local = worldToCup(p.x, p.y);
    var lv = velocityToCup(p.vx, p.vy);
    var escaped = false;

    if (local.y < cupFrame.topY - p.r * 1.4) {
      escaped = true;
    }

    if (!escaped && local.y > cupFrame.bottomY - p.r) {
      local.y = cupFrame.bottomY - p.r;
      if (lv.y > 0) {
        lv.y *= -0.22;
        lv.x *= 0.78;
        maybeEntrainedFromImpact(p, Math.abs(lv.y));
      }
    }

    if (!escaped && local.y > cupFrame.topY - p.r && local.y < cupFrame.bottomY + p.r) {
      var half = halfWidthAtLocalY(local.y);
      var slope = (cupFrame.bottomHalf - cupFrame.topHalf) / cup.height;
      if (local.x > half - p.r) {
        local.x = half - p.r;
        reflectLocalVelocity(lv, -1, slope, 0.28, 0.72);
      } else if (local.x < -half + p.r) {
        local.x = -half + p.r;
        reflectLocalVelocity(lv, 1, slope, 0.28, 0.72);
      }
    }

    if (escaped) {
      p.contained = false;
      p.escaped = true;
      spilledCount++;
      return;
    }

    var world = cupToWorld(local.x, local.y);
    var wv = velocityToWorld(lv.x, lv.y);
    p.x = world.x;
    p.y = world.y;
    p.vx = wv.x;
    p.vy = wv.y;
  }

  function reflectLocalVelocity(v, nx, ny, restitution, tangentDamping) {
    var length = Math.sqrt(nx * nx + ny * ny) || 1;
    nx /= length;
    ny /= length;
    var dot = v.x * nx + v.y * ny;
    if (dot < 0) {
      v.x -= (1 + restitution) * dot * nx;
      v.y -= (1 + restitution) * dot * ny;
      var tx = -ny;
      var ty = nx;
      var tangent = v.x * tx + v.y * ty;
      v.x += tx * tangent * (tangentDamping - 1);
      v.y += ty * tangent * (tangentDamping - 1);
    }
  }

  function entrainAir(p) {
    var c = currentControls;
    var speed = Math.sqrt(p.vx * p.vx + p.vy * p.vy);
    if (speed < 260 || particles.length < 45) {
      return;
    }
    var count = Math.floor(clamp((speed - 240) / 260, 0, 3) * c.aeration);
    for (var i = 0; i < count && bubbles.length < 700; i++) {
      bubbles.push({
        x: p.x + random(-18, 18),
        y: p.y + random(10, 56),
        vx: random(-18, 18) + p.vx * 0.012,
        vy: random(-36, -6),
        r: random(4, 13),
        life: random(2.5, 6.5),
        contained: true
      });
    }
  }

  function maybeEntrainedFromImpact(p, speed) {
    if (speed < 120 || bubbles.length > 700) {
      return;
    }
    if (Math.random() < 0.12 * currentControls.aeration) {
      bubbles.push({
        x: p.x + random(-15, 15),
        y: p.y - random(12, 48),
        vx: random(-16, 16),
        vy: random(-50, -15),
        r: random(3, 10),
        life: random(2, 5),
        contained: true
      });
    }
  }

  function updateBubbles(dt) {
    var next = [];
    for (var i = 0; i < bubbles.length; i++) {
      var b = bubbles[i];
      b.life -= dt;
      b.vx += Math.sin(simTime * 4 + b.y * 0.02) * 12 * dt;
      b.vy -= (38 + b.r * 5) * dt;
      b.x += b.vx * dt;
      b.y += b.vy * dt;

      var local = worldToCup(b.x, b.y);
      if (local.y < cupFrame.topY + 10) {
        foam.push({ x: b.x, y: b.y, vx: b.vx * 0.2, r: b.r * random(0.8, 1.35), life: random(2.0, 5.5) });
        continue;
      }

      if (b.life > 0 && local.y < cupFrame.bottomY && Math.abs(local.x) < halfWidthAtLocalY(local.y) - 4) {
        next.push(b);
      }
    }
    bubbles = next;
  }

  function updateFoam(dt) {
    var next = [];
    for (var i = 0; i < foam.length; i++) {
      var f = foam[i];
      f.life -= dt * 0.42;
      f.x += f.vx * dt + Math.sin(simTime * 2 + i) * dt * 4;
      f.y += Math.sin(simTime * 3 + i) * dt * 5;
      if (f.life > 0 && f.y < SIM_H + 60) {
        next.push(f);
      }
    }
    foam = next;
  }

  function pruneEscaped() {
    var next = [];
    containedCount = 0;
    var escapedLive = 0;
    for (var i = 0; i < particles.length; i++) {
      var p = particles[i];
      if (p.contained) {
        containedCount++;
      } else if (p.escaped) {
        escapedLive++;
      }
      if (p.y < SIM_H + 80 && p.x > -120 && p.x < SIM_W + 120 && p.age < 18) {
        next.push(p);
      }
    }
    particles = next;
    spilledCount = Math.min(9999, spilledCount + Math.max(0, escapedLive - 240) * 0.002);
  }

  function buildFields() {
    waterField.fill(0);
    airField.fill(0);

    for (var i = 0; i < particles.length; i++) {
      var p = particles[i];
      splat(waterField, p.x, p.y, p.r * 2.25, p.contained ? 0.52 : 0.72);
    }

    for (var j = 0; j < bubbles.length; j++) {
      var b = bubbles[j];
      splat(airField, b.x, b.y, b.r * 1.85, 0.7);
    }

    for (var k = 0; k < foam.length; k++) {
      var f = foam[k];
      splat(airField, f.x, f.y, f.r * 1.7, 0.55);
    }

    for (var n = 0; n < waterField.length; n++) {
      waterField[n] = clamp(waterField[n] - airField[n] * 0.82, 0, 1);
    }
  }

  function splat(target, x, y, radius, strength) {
    var gx = (x / SIM_W) * FIELD_W;
    var gy = (y / SIM_H) * FIELD_H;
    var gr = Math.max(1.1, (radius / SIM_W) * FIELD_W);
    var minX = Math.max(0, Math.floor(gx - gr * 2));
    var maxX = Math.min(FIELD_W - 1, Math.ceil(gx + gr * 2));
    var minY = Math.max(0, Math.floor(gy - gr * 2));
    var maxY = Math.min(FIELD_H - 1, Math.ceil(gy + gr * 2));
    var support = gr * gr * 4;

    for (var yy = minY; yy <= maxY; yy++) {
      var dy = yy - gy;
      for (var xx = minX; xx <= maxX; xx++) {
        var dx = xx - gx;
        var d2 = dx * dx + dy * dy;
        if (d2 > support) {
          continue;
        }
        var falloff = 1 - d2 / support;
        falloff *= falloff;
        var index = yy * FIELD_W + xx;
        target[index] = Math.min(1, target[index] + falloff * strength);
      }
    }
  }

  function renderFieldImage() {
    var data = imageData.data;
    for (var i = 0; i < waterField.length; i++) {
      var color;
      if (layer === "air") {
        color = colorAir(airField[i], waterField[i]);
      } else if (layer === "glass") {
        color = colorGlass(waterField[i], airField[i]);
      } else {
        color = colorVof(waterField[i]);
      }
      var p = i * 4;
      data[p] = color[0];
      data[p + 1] = color[1];
      data[p + 2] = color[2];
      data[p + 3] = color[3];
    }
    fieldCtx.putImageData(imageData, 0, 0);
  }

  function colorVof(value) {
    var v = clamp(value, 0, 1);
    if (v < 0.06) return [0, 91, 255, 255];
    if (v < 0.17) return [0, 146, 255, 255];
    if (v < 0.28) return [0, 205, 239, 255];
    if (v < 0.39) return [29, 216, 177, 255];
    if (v < 0.5) return [0, 196, 48, 255];
    if (v < 0.61) return [142, 232, 0, 255];
    if (v < 0.72) return [244, 239, 0, 255];
    if (v < 0.84) return [255, 183, 0, 255];
    return [255, 100, 0, 255];
  }

  function colorAir(air, water) {
    var a = clamp(air, 0, 1);
    var w = clamp(water, 0, 1);
    if (a < 0.02 && w < 0.02) return [5, 18, 48, 255];
    if (a < 0.02) return [12, 67, 120, 255];
    return [13 + a * 242, 85 + a * 170, 142 + a * 113, 255];
  }

  function colorGlass(water, air) {
    var w = clamp(water, 0, 1);
    var a = clamp(air, 0, 1);
    if (w < 0.02 && a < 0.02) return [255, 255, 255, 0];
    if (a > 0.04) return [230 + a * 25, 248 + a * 7, 255, clamp(90 + a * 165, 0, 255)];
    return [26, 121 + w * 62, 215 + w * 28, clamp(45 + w * 150, 0, 220)];
  }

  function render() {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = layer === "air" ? "#051230" : layer === "glass" ? "#f8fbff" : "#005bff";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    updateView();
    ctx.save();
    ctx.translate(view.x, view.y);
    ctx.scale(view.scale, view.scale);

    if (layer === "glass") {
      drawGlassScene();
    } else {
      drawFieldScene();
    }

    ctx.restore();
  }

  function drawFieldScene() {
    ctx.fillStyle = layer === "air" ? "#051230" : "#005bff";
    ctx.fillRect(0, 0, SIM_W, SIM_H);
    ctx.imageSmoothingEnabled = true;
    ctx.drawImage(fieldCanvas, 0, 0, SIM_W, SIM_H);
    drawFaucet(false);
    drawCup(false);
    drawParticleOutlines();
    drawAxes();
  }

  function drawGlassScene() {
    drawShadow();
    drawCup(true);
    ctx.imageSmoothingEnabled = true;
    ctx.drawImage(fieldCanvas, 0, 0, SIM_W, SIM_H);
    drawFaucet(true);
    drawParticleHighlights();
    drawCupHighlights();
  }

  function drawFaucet(glassy) {
    var dir = faucetDirection();
    var noz = nozzlePosition();
    var normal = { x: -dir.y, y: dir.x };
    ctx.save();
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.strokeStyle = glassy ? "#8295a2" : "#163b70";
    ctx.fillStyle = glassy ? "#d5dee5" : "#dbeeff";
    ctx.lineWidth = glassy ? 8 : 5;
    ctx.beginPath();
    ctx.moveTo(faucet.x - 92, faucet.y - 22);
    ctx.lineTo(faucet.x + 92, faucet.y - 22);
    ctx.stroke();
    ctx.lineWidth = glassy ? 28 : 23;
    ctx.beginPath();
    ctx.moveTo(faucet.x, faucet.y);
    ctx.lineTo(noz.x, noz.y);
    ctx.stroke();
    ctx.fillStyle = glassy ? "#aab8c2" : "#95b8e8";
    ctx.beginPath();
    ctx.moveTo(noz.x + normal.x * 25, noz.y + normal.y * 25);
    ctx.lineTo(noz.x - normal.x * 25, noz.y - normal.y * 25);
    ctx.lineTo(noz.x - normal.x * 17 + dir.x * 16, noz.y - normal.y * 17 + dir.y * 16);
    ctx.lineTo(noz.x + normal.x * 17 + dir.x * 16, noz.y + normal.y * 17 + dir.y * 16);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = glassy ? "#6e7f8b" : "#173d70";
    ctx.lineWidth = 6;
    ctx.translate(faucet.x + 108, faucet.y - 22);
    ctx.rotate(currentControls.valve * Math.PI * 0.85);
    ctx.beginPath();
    ctx.moveTo(-24, 0);
    ctx.lineTo(24, 0);
    ctx.moveTo(0, -18);
    ctx.lineTo(0, 18);
    ctx.stroke();
    ctx.restore();
  }

  function drawCup(glassy) {
    var v = cupVertices();
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(v[0].x, v[0].y);
    ctx.lineTo(v[1].x, v[1].y);
    ctx.lineTo(v[2].x, v[2].y);
    ctx.lineTo(v[3].x, v[3].y);
    ctx.closePath();
    ctx.fillStyle = glassy ? "rgba(210, 228, 239, 0.16)" : "rgba(0, 37, 99, 0.05)";
    ctx.fill();
    ctx.lineWidth = glassy ? 8 : 3;
    ctx.strokeStyle = glassy ? "rgba(160, 179, 190, 0.76)" : layer === "air" ? "rgba(223, 246, 255, 0.86)" : "#dbeeff";
    ctx.beginPath();
    ctx.moveTo(v[0].x, v[0].y);
    ctx.lineTo(v[3].x, v[3].y);
    ctx.lineTo(v[2].x, v[2].y);
    ctx.lineTo(v[1].x, v[1].y);
    ctx.stroke();
    ctx.globalAlpha = glassy ? 0.42 : 0.26;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(v[0].x, v[0].y);
    ctx.lineTo(v[1].x, v[1].y);
    ctx.stroke();
    ctx.restore();
  }

  function drawParticleOutlines() {
    if (layer !== "vof") {
      return;
    }
    ctx.save();
    ctx.strokeStyle = "rgba(225, 255, 255, 0.38)";
    ctx.lineWidth = 1.2;
    for (var i = 0; i < bubbles.length; i += 2) {
      var b = bubbles[i];
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r * 0.9, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.restore();
  }

  function drawParticleHighlights() {
    ctx.save();
    for (var i = 0; i < bubbles.length; i += 2) {
      var b = bubbles[i];
      ctx.strokeStyle = "rgba(255, 255, 255, 0.72)";
      ctx.lineWidth = 1.3;
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r * 0.9, 0, Math.PI * 2);
      ctx.stroke();
    }
    for (var j = 0; j < foam.length; j += 2) {
      var f = foam[j];
      ctx.fillStyle = "rgba(255, 255, 255, 0.7)";
      ctx.beginPath();
      ctx.arc(f.x, f.y, f.r * 0.62, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }

  function drawCupHighlights() {
    var v = cupVertices();
    ctx.save();
    ctx.strokeStyle = "rgba(255, 255, 255, 0.68)";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(v[0].x + 18, v[0].y + 20);
    ctx.lineTo(v[3].x + 24, v[3].y - 22);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(v[1].x - 26, v[1].y + 20);
    ctx.lineTo(v[2].x - 24, v[2].y - 22);
    ctx.stroke();
    ctx.restore();
  }

  function drawShadow() {
    ctx.save();
    ctx.fillStyle = "rgba(20, 35, 52, 0.12)";
    ctx.beginPath();
    ctx.ellipse(cup.cx, cup.cy + cup.height * 0.5 + 20, 230, 28, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  function drawAxes() {
    ctx.save();
    ctx.translate(908, 572);
    ctx.lineWidth = 4;
    ctx.strokeStyle = "#f33423";
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(54, 0);
    ctx.stroke();
    ctx.fillStyle = "#f33423";
    ctx.beginPath();
    ctx.moveTo(62, 0);
    ctx.lineTo(45, -9);
    ctx.lineTo(45, 9);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "#20b949";
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(0, -58);
    ctx.stroke();
    ctx.fillStyle = "#20b949";
    ctx.beginPath();
    ctx.moveTo(0, -66);
    ctx.lineTo(-9, -48);
    ctx.lineTo(9, -48);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = "#0d47d7";
    ctx.beginPath();
    ctx.arc(0, 0, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  function updateView() {
    var cssW = canvas.clientWidth;
    var cssH = canvas.clientHeight;
    var scale = Math.min(cssW / SIM_W, cssH / SIM_H);
    view.x = (cssW - SIM_W * scale) * 0.5;
    view.y = (cssH - SIM_H * scale) * 0.5;
    view.scale = scale;
  }

  function resize() {
    dpr = Math.min(window.devicePixelRatio || 1, DPR_LIMIT);
    var rect = canvas.getBoundingClientRect();
    canvas.width = Math.max(1, Math.floor(rect.width * dpr));
    canvas.height = Math.max(1, Math.floor(rect.height * dpr));
  }

  function updateStats() {
    particleValue.textContent = String(particles.length);
    fillValue.textContent = String(Math.round((containedCount / MAX_PARTICLES) * 100)) + "%";
    foamValue.textContent = String(bubbles.length + foam.length);
  }

  function setLayer(nextLayer) {
    layer = nextLayer;
    app.dataset.layer = layer;
    layerButtons.forEach(function (button) {
      button.classList.toggle("active", button.dataset.layerButton === layer);
    });

    if (layer === "air") {
      fieldTitle.textContent = "Air/Foam Fraction";
      fieldSubtitle.textContent = "physical bubbles + surface foam";
      legendLabels.innerHTML = "<span>high</span><span>foam</span><span>bubbles</span><span>low</span>";
    } else if (layer === "glass") {
      fieldTitle.textContent = "Water + Air";
      fieldSubtitle.textContent = "transparent glass view";
      legendLabels.innerHTML = "<span>water</span><span>mix</span><span>air</span><span>0</span>";
    } else {
      fieldTitle.textContent = "Water.Volume Fraction";
      fieldSubtitle.textContent = "particle physics VOF";
      legendLabels.innerHTML =
        "<span>1.000e+00</span><span>8.889e-01</span><span>7.778e-01</span><span>6.667e-01</span><span>5.556e-01</span><span>4.444e-01</span><span>3.333e-01</span><span>2.222e-01</span><span>1.111e-01</span><span>0.000e+00</span>";
    }
  }

  function tick(now) {
    var rawDt = Math.min(0.05, (now - lastTime) / 1000);
    lastTime = now;

    if (running) {
      simAccumulator += rawDt;
      var steps = 0;
      while (simAccumulator >= FIXED_STEP && steps < 3) {
        update(FIXED_STEP);
        simAccumulator -= FIXED_STEP;
        steps++;
      }
      if (simAccumulator > FIXED_STEP * 3) {
        simAccumulator = 0;
      }
    }

    render();
    frameCount++;
    frameAccumulator += rawDt;
    if (now - lastFpsUpdate > 350) {
      fpsValue.textContent = String(Math.round(frameCount / Math.max(frameAccumulator, 0.001)));
      frameCount = 0;
      frameAccumulator = 0;
      lastFpsUpdate = now;
    }
    requestAnimationFrame(tick);
  }

  layerButtons.forEach(function (button) {
    button.addEventListener("click", function () {
      setLayer(button.dataset.layerButton);
      renderFieldImage();
    });
  });

  runButton.addEventListener("click", function () {
    running = !running;
    runButton.textContent = running ? "Pause" : "Run";
  });

  resetButton.addEventListener("click", function () {
    resetSimulation();
    buildFields();
    renderFieldImage();
    updateStats();
  });

  resolutionControl.addEventListener("input", function () {
    initField();
    buildFields();
    renderFieldImage();
  });

  window.addEventListener("resize", resize);
  initField();
  resetSimulation();
  setLayer("vof");
  resize();
  buildFields();
  renderFieldImage();
  updateStats();
  requestAnimationFrame(tick);
})();

